@@ -3044,10 +3034,0 @@
-// 64 bit integer valid for sub immediate
-operand immLSub()
-%{
-  predicate(Assembler::is_simm12(-(n->get_long())));
-  match(ConL);
-  op_cost(0);
-  format %{ %}
-  interface(CONST_INTER);
-%}
